<?php
require_once __DIR__.'/../app/bootstrap.php';require_role(['system_admin','cooperative_manager']);$pdo=db();$user=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){require_role(['system_admin']);verify_csrf();$name=trim((string)($_POST['name']??''));$reg=trim((string)($_POST['registration_number']??''));$district=trim((string)($_POST['district']??''));$sector=trim((string)($_POST['sector']??''));$phone=trim((string)($_POST['phone']??''));$email=trim((string)($_POST['email']??''));if($name===''||$reg===''){flash('error','Cooperative name and registration number are required.');redirect('cooperatives.php');}if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL)){flash('error','Enter a valid email.');redirect('cooperatives.php');}try{$pdo->prepare('INSERT INTO cooperatives (name,registration_number,district,sector,phone,email) VALUES (?,?,?,?,?,?)')->execute([$name,$reg,$district?:null,$sector?:null,$phone?:null,$email?:null]);flash('success','Cooperative created successfully.');}catch(PDOException $e){flash('error','Could not create cooperative. Registration number may already exist.');}redirect('cooperatives.php');}
if($user['role']==='system_admin') { $rows=$pdo->query('SELECT c.*,COUNT(m.id) member_count FROM cooperatives c LEFT JOIN members m ON m.cooperative_id=c.id GROUP BY c.id ORDER BY c.created_at DESC')->fetchAll(); } else { $st=$pdo->prepare('SELECT c.*,COUNT(m.id) member_count FROM cooperatives c LEFT JOIN members m ON m.cooperative_id=c.id WHERE c.id=? GROUP BY c.id'); $st->execute([(int)$user['cooperative_id']]); $rows=$st->fetchAll(); }
$pageTitle='Cooperatives';require __DIR__.'/includes/header.php';?><div class="welcome-row"><div><h2>Cooperative directory</h2><p class="muted">View and register cooperative organizations.</p></div></div><?php if($user['role']==='system_admin'): ?><section class="panel"><div class="panel-heading"><div><h3>Register a cooperative</h3><p class="muted">Enter the official registration details.</p></div></div><form method="post" class="form-grid compact-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Cooperative name *<input name="name" required maxlength="160"></label><label>Registration number *<input name="registration_number" required maxlength="80"></label><label>District<input name="district" maxlength="100"></label><label>Sector<input name="sector" maxlength="100"></label><label>Phone<input name="phone" maxlength="30"></label><label>Email<input name="email" type="email" maxlength="160"></label><div class="span-2 form-actions"><button class="btn primary" type="submit">Create cooperative →</button></div></form></section><?php endif; ?><section class="panel"><div class="panel-heading"><div><h3>Registered cooperatives</h3><p class="muted"><?= count($rows) ?> organization(s)</p></div></div><div class="table-wrap"><table><thead><tr><th>Cooperative</th><th>Registration no.</th><th>Location</th><th>Members</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $c): ?><tr><td><strong><?= e($c['name']) ?></strong><small class="subline"><?= e($c['email']??'') ?></small></td><td><?= e($c['registration_number']) ?></td><td><?= e(trim(($c['district']??'').' · '.($c['sector']??''),' ·')) ?: '—' ?></td><td><?= (int)$c['member_count'] ?></td><td><span class="badge <?= e($c['status']) ?>"><?= e(ucfirst($c['status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div></section><?php require __DIR__.'/includes/footer.php'; ?>
